PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, license TEXT NOT NULL, version TEXT NOT NULL, obtained_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS artists(id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id));
CREATE INDEX IF NOT EXISTS artist_name_idx ON artists(normalized_name);
CREATE TABLE IF NOT EXISTS labels(id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id));
CREATE INDEX IF NOT EXISTS label_name_idx ON labels(normalized_name);
CREATE TABLE IF NOT EXISTS recordings(id TEXT PRIMARY KEY, title TEXT NOT NULL, normalized_title TEXT NOT NULL, version TEXT NOT NULL, primary_artist_id TEXT NOT NULL REFERENCES artists(id), duration_ms INTEGER, source_id TEXT NOT NULL REFERENCES sources(id));
CREATE INDEX IF NOT EXISTS recording_name_idx ON recordings(normalized_title, primary_artist_id, version);
CREATE TABLE IF NOT EXISTS recording_artists(recording_id TEXT NOT NULL REFERENCES recordings(id), artist_id TEXT NOT NULL REFERENCES artists(id), role TEXT NOT NULL CHECK(role IN ('primary','featured','remixer')), PRIMARY KEY(recording_id,artist_id,role));
CREATE TABLE IF NOT EXISTS recording_identifiers(recording_id TEXT NOT NULL REFERENCES recordings(id), namespace TEXT NOT NULL, value TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), PRIMARY KEY(recording_id,namespace,value));
CREATE INDEX IF NOT EXISTS identifier_idx ON recording_identifiers(namespace,value);
CREATE TABLE IF NOT EXISTS releases(id TEXT PRIMARY KEY, title TEXT NOT NULL, release_date TEXT, compilation INTEGER NOT NULL DEFAULT 0, source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS release_tracks(release_id TEXT NOT NULL REFERENCES releases(id), position INTEGER NOT NULL, recording_id TEXT NOT NULL REFERENCES recordings(id), PRIMARY KEY(release_id,position));
CREATE INDEX IF NOT EXISTS release_recording_idx ON release_tracks(recording_id);
CREATE TABLE IF NOT EXISTS release_labels(release_id TEXT NOT NULL REFERENCES releases(id), label_id TEXT NOT NULL REFERENCES labels(id), PRIMARY KEY(release_id,label_id));
CREATE TABLE IF NOT EXISTS genres(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS annotations(entity_type TEXT NOT NULL CHECK(entity_type IN ('recording','release')), entity_id TEXT NOT NULL, genre_id INTEGER NOT NULL REFERENCES genres(id), source_id TEXT NOT NULL REFERENCES sources(id), PRIMARY KEY(entity_type,entity_id,genre_id,source_id));
CREATE INDEX IF NOT EXISTS annotation_entity_idx ON annotations(entity_type,entity_id);
CREATE TABLE IF NOT EXISTS genre_distributions(entity_type TEXT NOT NULL CHECK(entity_type IN ('artist','label')), entity_id TEXT NOT NULL, family TEXT NOT NULL, recordings INTEGER NOT NULL, tagged_recordings INTEGER NOT NULL, total_recordings INTEGER NOT NULL, policy_version TEXT NOT NULL, source_ids TEXT NOT NULL, PRIMARY KEY(entity_type,entity_id,family));
